import unittest
from datetime import datetime, timezone, timedelta
from solution import is_expired

NOW = datetime(2026, 7, 1, 12, 0, tzinfo=timezone.utc)

class T(unittest.TestCase):
    def test_past_aware(self):
        self.assertTrue(is_expired(NOW - timedelta(hours=1), NOW))
    def test_future_aware(self):
        self.assertFalse(is_expired(NOW + timedelta(hours=1), NOW))
    def test_naive_is_treated_as_utc(self):
        self.assertTrue(is_expired(datetime(2026, 7, 1, 11, 0), NOW))
        self.assertFalse(is_expired(datetime(2026, 7, 1, 13, 0), NOW))
    def test_other_offset(self):
        kst = timezone(timedelta(hours=9))
        self.assertFalse(is_expired(datetime(2026, 7, 1, 22, 0, tzinfo=kst), NOW))

import unittest
from solution import prune_empty

class T(unittest.TestCase):
    def test_removes_empty(self):
        self.assertEqual(prune_empty({"a": 1, "b": None, "c": "", "d": 0}),
                         {"a": 1, "d": 0})
    def test_all_empty(self):
        self.assertEqual(prune_empty({"a": None, "b": ""}), {})
    def test_does_not_mutate_input(self):
        src = {"a": None, "b": 2}
        prune_empty(src)
        self.assertEqual(src, {"a": None, "b": 2})
    def test_many_keys(self):
        src = {str(i): (None if i % 2 else i) for i in range(50)}
        self.assertEqual(len(prune_empty(src)), 25)

